// floor cells they can't reach), its floor as a grid with the furniture drawn in, its light levels at night, and where
// a lantern would clear the dark and dim cells. The room designers ran make -> walk -> light -> rooms, then rebuilt by
// trial and error; this is that loop's reading side as text.
import { walkReport, floorPlan } from "./rooms.mjs";
import { lightField, lightMaps } from "./light.mjs";

const strip = (n) => String(n).replace(/^minecraft:/, "");
const PASS = /air$|carpet|pressure_plate|torch|_button|lever|flower$|tulip|grass$|fern$|sapling|snow$|vine|ladder|_sign$|banner$|candle$|light$|water$|bubble_column|kelp|seagrass|scaffolding|_door$|fence_gate$|bush$|poppy|dandelion|orchid|allium|bluet|daisy|cornflower|lily_of|azalea$|moss_carpet|rail$|redstone_wire/;

/** Lantern spots (at most `most`) that lift the room's floor cells below level 8, best first: hanging from the ceiling
 * where the room is 3+ high (out of the way), else on the floor against a wall. Greedy, by cells lifted to 8+. */
export function suggestLights(grid, box, { most = 3 } = {}) {
  const [x0, y0, z0, x1, y1, z1] = box;
  const pass = (x, y, z) => !grid.inBounds(x, y, z) || PASS.test(strip(grid.blockAt(x, y, z)));
  const floor = [];
  for (let x = x0; x <= x1; x++) for (let z = z0; z <= z1; z++)
    for (let y = y0; y <= y1; y++) if (pass(x, y, z) && pass(x, y + 1, z) && grid.inBounds(x, y - 1, z) && !pass(x, y - 1, z)) { floor.push([x, y, z]); break; }
  const cands = [];
  for (const [x, y, z] of floor) {
    let top = y + 1;
    while (top + 1 <= y1 + 1 && grid.inBounds(x, top + 1, z) && grid.isAir(x, top + 1, z)) top++;
    if (top >= y + 2 && grid.inBounds(x, top + 1, z) && !grid.isAir(x, top + 1, z)) cands.push({ at: [x, top, z], how: "hanging lantern (lantern[hanging=true]) under the ceiling" });
