    if (wall) cands.push({ at: [x, y, z], how: "lantern on the floor against the wall" });
  }
  const lowCells = (F) => floor.filter(([x, y, z]) => F.level(x, y, z) < 8).length;
  let base = lowCells(lightField(grid));
  const picks = [];
  while (picks.length < most && base > 0 && cands.length) {
    let best = null;
    for (const c of cands) {
      const [x, y, z] = c.at, was = grid.get(x, y, z);
      grid.set(x, y, z, "minecraft:lantern", c.how.startsWith("hanging") ? { hanging: "true" } : undefined);
      const left = lowCells(lightField(grid));
      if (was) grid.set(x, y, z, was.block, was.state, was.nbt); else grid.unset(x, y, z);
      if (!best || left < best.left) best = { ...c, left };
    }
    if (!best || best.left >= base) break;
    picks.push({ ...best, lifts: base - best.left });
    const [x, y, z] = best.at;
    grid.set(x, y, z, "minecraft:lantern", best.how.startsWith("hanging") ? { hanging: "true" } : undefined);   // keep it for the next pick
    base = best.left;
    cands.splice(cands.findIndex((c) => c.at === best.at), 1);
  }
  for (const p of picks) grid.unset(...p.at);
  return picks;
}

